// PiP Window Logic
const PiPWindow = ({ children, onClose }: { children: React.ReactNode, onClose: () => void }) => {
    const [container, setContainer] = useState<HTMLElement | null>(null);

    useEffect(() => {
        if (!window.documentPictureInPicture) {
            alert("Your browser does not support Document Picture-in-Picture (Pop-out). Please use Chrome 111+ or Edge.");
            onClose();
            return;
        }

        async function initPip() {
            try {
                // Request a vertical phone-like window
                const pipWindow = await window.documentPictureInPicture.requestWindow({
                    width: 450,
                    height: 700,
                });

                // Inject Tailwind CDN
                const twScript = pipWindow.document.createElement('script');
                twScript.src = "https://cdn.tailwindcss.com";
                // Inject config (replicate from index.html)
                twScript.onload = () => {
                   const configScript = pipWindow.document.createElement('script');
                   configScript.innerHTML = `
                      tailwind.config = {
                        theme: {
                          extend: {
                            colors: {
                              background: '#09090b',
                              surface: '#18181b',
                              primary: '#3b82f6',
                              accent: '#f59e0b',
                            },
                          },
                        },
                      }
                   `;
                   pipWindow.document.head.appendChild(configScript);
                };
                pipWindow.document.head.appendChild(twScript);

                // Inject Styles
                const style = pipWindow.document.createElement('style');
                style.textContent = `
                  ::-webkit-scrollbar { width: 8px; }
                  ::-webkit-scrollbar-track { background: #18181b; }
                  ::-webkit-scrollbar-thumb { background: #3f3f46; border-radius: 4px; }
                  body { background-color: #09090b; margin: 0; overflow: hidden; font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; }
                `;
                pipWindow.document.head.appendChild(style);

                const div = pipWindow.document.createElement('div');
                div.style.height = '100%';
                div.style.display = 'flex';
                div.style.flexDirection = 'column';
                pipWindow.document.body.appendChild(div);
                setContainer(div);

                pipWindow.addEventListener("pagehide", () => {
                    onClose();
                });
            } catch (err) {
                console.error("PiP Error:", err);
                onClose();
            }
        }
        initPip();
    }, []);

    if (!container) return null;
    return createPortal(children, container);
};


export default function App() {
  // --- State ---
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState("");
  const [interimText, setInterimText] = useState("");

  const [isProcessing, setIsProcessing] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showContext, setShowContext] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const [showMobileMenu, setShowMobileMenu] = useState(false);

  // PiP State
  const [isPipMode, setIsPipMode] = useState(false);

  const [settings, setSettings] = useState<AppSettings>({
    apiKey: localStorage.getItem("GEMINI_API_KEY") || "",
    autoSend: false, 
    contextFiles: [
      { id: '1', name: 'Placeholder Resume', content: INITIAL_RESUME_TEXT, type: 'resume' },
      { id: '2', name: 'Placeholder JD', content: INITIAL_JD_TEXT, type: 'jd' }
    ]
  });

  // Scroll State
  const [shouldAutoScroll, setShouldAutoScroll] = useState(true);

  // Ref pattern to fix closure staleness in callbacks
  const settingsRef = useRef(settings);
  useEffect(() => { settingsRef.current = settings; }, [settings]);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const silenceTimerRef = useRef<any>(null);
  const inputTextRef = useRef(inputText);

  useEffect(() => {
    inputTextRef.current = inputText;
    if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        const newHeight = Math.min(textareaRef.current.scrollHeight, 150);
        textareaRef.current.style.height = newHeight + 'px';
    }
  }, [inputText]);

  // --- Initialization ---
  useEffect(() => {
    if (settings.apiKey) {
      geminiService.init(settings.apiKey);
    }
  }, [settings.apiKey]);

  // Handle Auto-Scrolling
  useEffect(() => {
    if (shouldAutoScroll && chatContainerRef.current) {
      chatContainerRef.current.scrollTo({
          top: chatContainerRef.current.scrollHeight,
          behavior: 'smooth'
      });
    }
  }, [messages, interimText, shouldAutoScroll]);

  const handleScroll = () => {
      if (!chatContainerRef.current) return;
      const { scrollTop, scrollHeight, clientHeight } = chatContainerRef.current;
      const isAtBottom = scrollHeight - scrollTop - clientHeight < 50;
      setShouldAutoScroll(isAtBottom);
  };

  // --- Core Logic ---
  const executeSend = useCallback(async (textToSend: string) => {
      if (!textToSend.trim()) return;

      const userMsg: Message = {
        id: Date.now().toString(),
        role: 'user',
        content: textToSend,
        timestamp: Date.now()
      };

      setMessages(prev => [...prev, userMsg]);
      setIsProcessing(true);
      setInterimText("");
      setInputText(""); 
      setShouldAutoScroll(true); 

      try {
        const currentSettings = settingsRef.current;
        const responseText = await geminiService.generateResponse(
          userMsg.content,
          messages, 
          currentSettings.contextFiles
        );

        if (responseText !== "Listening...") {
            const aiMsg: Message = {
              id: (Date.now() + 1).toString(),
              role: 'model',
              content: responseText,
              timestamp: Date.now()
            };
            setMessages(prev => [...prev, aiMsg]);
        }
      } catch (err) {
        console.error(err);
        const errorMsg: Message = {
          id: Date.now().toString(),
          role: 'system',
          content: "Error generating response. Check API Key.",
          timestamp: Date.now()
        };
        setMessages(prev => [...prev, errorMsg]);
      } finally {
        setIsProcessing(false);
      }
  }, [messages]); 

  // --- Speech Handling ---
  const handleSpeechResult = useCallback(({ final, interim }: { final: string, interim: string }) => {
    setInterimText(interim);
    if (interim && silenceTimerRef.current) {
        clearTimeout(silenceTimerRef.current);
        silenceTimerRef.current = null;
    }
    if (final) {
        setInputText(prev => {
            const separator = prev.length > 0 && !prev.endsWith(' ') ? " " : "";
            return prev + separator + final;
        });
        if (settingsRef.current.autoSend) {
            if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
            silenceTimerRef.current = setTimeout(() => {
                const currentBuffer = inputTextRef.current;
                if (currentBuffer && currentBuffer.trim().length > 0) {
                     executeSend(currentBuffer);
                }
            }, 1200); 
        }
    }
  }, [executeSend]);

  const { isListening, error: speechError, startListening, stopListening } = useSpeechRecognition({
    onResult: handleSpeechResult,
    onError: (err) => console.error("Speech Error:", err)
  });

  useEffect(() => {
      if (settings.autoSend && !isListening) {
          startListening();
      }
  }, [settings.autoSend, isListening, startListening]);

  // --- UI Actions ---
  const handleManualSend = () => {
    if (!inputText.trim() || isProcessing) return;
    if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
    executeSend(inputText);
  };

  const handleClear = () => {
      setInputText("");
      if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
  };

  const handleRegenerate = async () => {
    if (isProcessing) return;
    const lastUserMsg = [...messages].reverse().find(m => m.role === 'user');
    if (!lastUserMsg) return;

    setIsProcessing(true);
    try {
        const historyForService = messages.filter(m => m.id !== lastUserMsg.id && m.role !== 'system');
        const responseText = await geminiService.generateResponse(
            lastUserMsg.content,
            historyForService,
            settingsRef.current.contextFiles
        );
        if (responseText !== "Listening...") {
            const aiMsg: Message = {
                id: Date.now().toString(),
                role: 'model',
                content: responseText,
                timestamp: Date.now()
            };
            setMessages(prev => [...prev, aiMsg]);
        }
    } catch (err) { console.error(err); } finally { setIsProcessing(false); }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const result = event.target?.result as string;
      const base64Data = result.split(',')[1];
      const mimeType = result.split(':')[1].split(';')[0];

      const newFile: ContextFile = {
        id: Date.now().toString(),
        name: file.name,
        content: "[Binary File]", 
        type: 'custom',
        mimeType: mimeType,
        base64: base64Data
      };
      setSettings(prev => ({ ...prev, contextFiles: [...prev.contextFiles, newFile] }));
    };
    reader.readAsDataURL(file);
  };

  const removeFile = (id: string) => {
    setSettings(prev => ({ ...prev, contextFiles: prev.contextFiles.filter(f => f.id !== id) }));
  };

  const toggleAutoSend = () => {
    setSettings(prev => ({ ...prev, autoSend: !prev.autoSend }));
  };

  const saveApiKey = (key: string) => {
    localStorage.setItem("GEMINI_API_KEY", key);
    setSettings(prev => ({ ...prev, apiKey: key }));
  };

  // --- RENDER HELPERS ---

  const sharedProps = {
    messages, settings, isListening, isProcessing, inputText, setInputText, interimText,
    speechError, toggleAutoSend, startListening, stopListening, handleManualSend,
    handleClear, handleRegenerate, chatContainerRef, textareaRef, handleScroll,
    onOpenSettings: () => setShowSettings(true),
    onOpenContext: () => setShowContext(true),
    isPipMode,
    togglePip: () => setIsPipMode(true)
  };

  // If PiP is active, we render a "Safe Screen" in the main window
  // and the ChatInterface in the PiP Window via Portal.

  return (
    <div className="h-[100dvh] flex flex-col bg-background text-gray-100 font-sans overflow-hidden">
        {/* Main Content Area (conditionally Safe Screen or Chat) */}
        {!isPipMode ? (
            <ChatInterface {...sharedProps} />
        ) : (
