                </div>
                <div>
                    <h2 className="text-2xl font-bold text-white mb-2">Copilot Active in Pop-out Window</h2>
                    <p className="text-gray-400 max-w-md mx-auto">
                        This tab is now "Safe to Share".<br/>
                        The AI interface has moved to a separate window that is hidden from screen share (if you share this window/tab).
                    </p>
                </div>
                <div className="p-4 bg-gray-900 rounded-lg border border-gray-800 text-left w-full max-w-lg">
                    <p className="text-xs text-gray-500 uppercase tracking-wider font-bold mb-2">Safe View Placeholder</p>
                    <div className="space-y-2">
                         <div className="h-4 bg-gray-800 rounded w-3/4"></div>
                         <div className="h-4 bg-gray-800 rounded w-1/2"></div>
